{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    for seg in segments:
        if not all(k in seg for k in ('name','importance','minimum','capacity')):
            raise ValueError("Missing keys")
    alloc = [seg['minimum'] for seg in segments]
    total = sum(alloc)
    while total < budget:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] < seg['capacity']:
                score = seg['importance'] / (alloc[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        total += 1
    by_name = {}
    for i, seg in enumerate(segments):
        by_name[seg['name']] = alloc[i]
    return {
        "allocations": alloc,
        "by_name": by_name,
        "total": total
    }"}
